function factionOpinionReply(text,npc,randomize=false) {
  const target=text.includes('бандит')?'bandit':text.includes('военн')?'military':text.includes('одиноч')?'loner':text.includes('долг')?'duty':text.includes('свобод')?'freedom':text.includes('монолит')?'monolith':null;
  const opinions={
    bandit:['С бандитами всё зависит от конкретного человека. Среди них есть те, кто держит слово, но чужому человеку я бы спину не подставлял.','Бандиты привыкли решать вопросы силой и выгодой. Иногда с ними можно договориться, но цену обещаний лучше проверять делом.'],
    military:['Военные держат периметр и действуют по приказам. Их порядок понятен, но к тем, кто не из их подразделения, они часто относятся как к подозреваемым.','С армейцами бывает спокойно, пока не пересекаешь их посты. Дисциплина у них есть, а вот доверия к посторонним немного.'],
    loner:['Одиночки не единая армия, а люди со своими историями. Есть надёжные ребята, есть те, кто думает только о собственном кармане.','Мне ближе самостоятельность одиночек, но без взаимовыручки здесь долго не протянешь.'],
    duty:['Долговцы верят в порядок и контроль опасностей. Их цель понятна, но не каждому по душе жить по уставу.','У Долга хватает дисциплинированных бойцов. Только иногда они слишком уверены, что знают, как Зоне следует существовать.'],
    freedom:['Свободовцы ценят независимость и исследования. Среди них встречаются интересные люди, хотя порой они недооценивают риск.','Свобода — хорошая вещь, пока не забываешь об ответственности за товарищей.'],
    monolith:['С Монолитом разговор короткий: держись подальше. Их поведение нельзя объяснить обычными фракционными спорами.','Сталкеры рассказывают о Монолите разное, но связываться с ними я не советую. Не всякую угрозу можно уладить словами.']
  };
  if (target && opinions[target]) return randomize?pick(opinions[target]):stablePick(opinions[target],`${npc?.id}:${target}`);
  const own=REPLIES.thoughts_faction[npc?.faction]||REPLIES.thoughts_faction.default;
  return randomize?pick(own):stablePick(own,`${npc?.id}:thoughts_faction`);
}

export function isRouteQuestion(rawText) {
  return resolveIntent(normalize(rawText), null)==='direction';
}

function resolveIntent(text, lastIntent) {
  if (text==='ку') return 'greeting';
  const routeCue=/(?:как\s+(?:(?:мне|лучше|туда|отсюда|до|можно)\s+){0,3}(?:пройти|добраться|попасть|дойти|выйти|доехать)|куда\s+(?:мне\s+)?(?:идти|двигаться|направиться|свернуть|пойти)|какой\s+(?:дорогой|путь|маршрут)|маршрут|путь\s+(?:до|к|на|в)|дорог(?:у|а|ой)\s+(?:до|к|на|в)|переход\s+(?:к|на|в)|где\s+(?:я(?:\s+(?:сейчас\s+)?(?:нахожусь|стою|тут|здесь))?|(?:находится|расположен|расположена|лежит|стоит)|вход|выход|сидорович|сидор|торговец|подвал)|сколько\s+идти|как\s+отсюда|(?:подскажи|расскажи|объясни)\s+(?:мне\s+)?(?:дорогу|путь|маршрут)|(?:можно\s+ли|есть\s+ли)\s+(?:пройти|попасть|добраться)|(?:мне\s+)?(?:нужно|надо)\s+(?:пройти|добраться|попасть|дойти)\s+(?:к|до|в|на)|(?:покажи|показать)\s+(?:мне\s+)?(?:путь|дорогу|маршрут)|(?:ближайший|соседний)\s+(?:выход|переход)|какие\s+(?:здесь\s+)?переходы|есть\s+ли\s+(?:здесь\s+)?(?:выход|переход))/.test(text);
  const locationTarget=matchLocationTarget(text);
  const openRouteQuestion=/(?:куда\s+(?:мне\s+)?(?:идти|двигаться|пойти)|какой\s+путь|как\s+отсюда\s+выбраться|где\s+я(?:\s+(?:сейчас\s+)?(?:нахожусь|стою|тут|здесь))?|какие\s+(?:здесь\s+)?переходы|ближайший\s+(?:выход|переход)|подскажи\s+(?:мне\s+)?(?:дорогу|путь|маршрут)|покажи\s+(?:мне\s+)?(?:путь|дорогу|маршрут)|(?:мне\s+)?(?:нужно|надо)\s+(?:пройти|добраться|попасть|дойти)\s+(?:к|до|в|на)|есть\s+ли\s+(?:здесь\s+)?(?:выход|переход)|как\s+пройти(?:\s+дальше)?)/.test(text);
  const ambiguousPlaceCue=/(?:блокпост|кпп|тоннел|туннел|лагер)/.test(text);
  if (routeCue && (locationTarget || openRouteQuestion || ambiguousPlaceCue)) return 'direction';
  const matchedIntents=INTENTS.flatMap(intent=>intent.keys.filter(key=>phraseMatches(text,key)).map(key=>({intent,key})));
  const focusedPriority={repair:10,quest_status:10,artifact_info:10,rest:10,radio:10,inventory:10,local_services:10,encyclopedia:10};
  const found=matchedIntents.sort((a,b)=>(focusedPriority[b.intent.id]||0)-(focusedPriority[a.intent.id]||0)||b.key.length-a.key.length)[0]?.intent;
  if(found) return found.id;
  // Semantic fallbacks catch natural phrasing that is not in the phrase lexicon.
  if (/(рюкзак|инвентар|мои вещи|припасы)/.test(text) && /(что|сколько|какие|есть|покажи|посмотреть|лежит|несу)/.test(text)) return 'inventory';
  if (/(ремонт|почин|полом|износ)/.test(text) && /(где|кто|можно|нужно|надо|сколько|почин|ремонт)/.test(text)) return 'repair';
  if (/(задан|квест|поручен)/.test(text) && /(мои|актив|статус|прогресс|какие|сколько|что осталось|выполнить)/.test(text)) return 'quest_status';
  const asksOpinion=/(что|как|почему|расскаж|дума|счит|мнен|опас|видел|знаеш|знаешь)/.test(text);
  if(asksOpinion && /(мутант|слеп|псевдо|плот|кровосос|кабан|звер|твар)/.test(text)) return 'thoughts_mutants';
  if(asksOpinion && /(аномал|воронк|карусел|трамплин|артефакт|радиац)/.test(text)) return 'thoughts_anomalies';
  if(asksOpinion && /(группиров|фракц|бандит|военн|одиноч|долг|свобод)/.test(text)) return 'thoughts_faction';
  if(asksOpinion && /(жизн|смысл|надежд|будущ|держатс)/.test(text)) return 'thoughts_life';
  if(/(погод|дожд|снег|туман|ветер|ночь|темно|светает|рассвет|закат)/.test(text)) return 'zone_situation';
  if(/^(а это|а он|а она|а оно|а что дальше|а дальше|и что дальше|что потом|а насчет этого|а по поводу этого|и как быть|и что теперь)/.test(text) && lastIntent) return 'followup';
  return 'general';
}

